-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.create_page(p_site_id uuid, p_slug text, p_title text)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.create_page(p_site_id uuid, p_slug text, p_title text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; new_page uuid;
BEGIN
  actor := app.require_actor();
  IF NOT app.can_publish(p_site_id) THEN
    RAISE EXCEPTION 'not permitted to manage pages on this site' USING ERRCODE = 'CMS02';
  END IF;
  -- Site FK lock before page path reservation.
  PERFORM 1 FROM public.sites WHERE id=p_site_id AND archived_at IS NULL FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'This site is unavailable for new pages.' USING ERRCODE='CMS04';END IF;
  INSERT INTO public.pages (site_id, slug, title) VALUES (p_site_id, lower(p_slug), p_title)
  RETURNING id INTO new_page;
  PERFORM app.write_audit(p_site_id, 'user', actor, 'page.create', 'page', new_page, NULL, NULL,
                          jsonb_build_object('slug', lower(p_slug)));
  RETURN new_page;
END
$function$
